# Let me check connectivity within each output value
def get_regions_by_value(output, threshold_val):
    n = len(output)
    visited = [[False]*n for _ in range(n)]
    regions = []

    for r in range(n):
        for c in range(n):
            if output[r][c] == threshold_val and not visited[r][c]:
                region = []
                queue = [(r, c)]
                visited[r][c] = True
                while queue:
                    cr, cc = queue.pop(0)
                    region.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < n and 0 <= nc < n:
                            if output[nr][nc] == threshold_val and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                regions.append(region)
    return regions

